import '@design-schema/lit';
import { html } from 'lit';
import type { ListboxItem } from '@design-schema/lit';

const ROLES: ListboxItem[] = [
  {
    group: 'Engineering',
    options: [
      { value: 'frontend', label: 'Frontend' },
      { value: 'backend', label: 'Backend' },
    ],
  },
  {
    group: 'Design',
    options: [
      { value: 'product', label: 'Product design' },
      { value: 'brand', label: 'Brand design' },
    ],
  },
];

html`
  <ds-select
    label="Role"
    name="role"
    .options=${ROLES}
    .defaultValue=${['frontend', 'backend', 'brand']}
    multiple
  ></ds-select>
`;

